WITH base_bal AS (    SELECT        CTACTB,        SUM(CASE WHEN REFERENCIA <= LAST_DAY(DATE(:VAR_DATA_REF_DRE)) THEN VLRLANC ELSE 0 END) AS soma_ate_atu,        SUM(CASE WHEN REFERENCIA <= LAST_DAY(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) THEN VLRLANC ELSE 0 END) AS soma_ate_ant    FROM IMP_BASE_BALANCETE    WHERE CODEMP = :VAR_EMPRESA_DRE    GROUP BY CTACTB),regras_contas AS (    SELECT DISTINCT        DET.ORDEM,        DET.NOME_GRUPO,        DET.COD_NOTA_EXPLICATIVA,        DETCTACTB.PADRAO_CTACTB,        DETCTACTB.SINAL    FROM ESTR_DEMONSTRATIVOS EST    INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_REFERENCIA DETREF ON DET.ID = DETREF.ID_DET_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_CTACTB DETCTACTB ON DETREF.ID = DETCTACTB.ID_DET_DEMONSTRATIVO_REFERENCIA    WHERE EST.ID = 1      AND DETREF.REFERENCIA = (          SELECT MAX(R.REFERENCIA)          FROM DET_DEMONSTRATIVO_REFERENCIA R          WHERE R.ID_DET_DEMONSTRATIVO = DET.ID            AND R.REFERENCIA <= DATE(:VAR_DATA_REF_DRE)      ))SELECT    R.ORDEM,    R.NOME_GRUPO,    R.COD_NOTA_EXPLICATIVA,    SUM(IFNULL(B.soma_ate_atu, 0) * R.SINAL) AS VLRLANC_ATU,    SUM(IFNULL(B.soma_ate_ant, 0) * R.SINAL) AS VLRLANC_ANTFROM regras_contas RLEFT JOIN base_bal B ON B.CTACTB LIKE R.PADRAO_CTACTBGROUP BY    R.ORDEM,    R.NOME_GRUPO,    R.COD_NOTA_EXPLICATIVAORDER BY R.ORDEM